   "actors": "Harrison Ford,Virginia Madsen,Paul Bettany",
   "synopsis": "Cuando Jack Stanfield (Interpretado por Harrison Ford), un especialista en seguridad informática de un banco, regresa a casa tras un día de trabajo para estar con su mujer Beth (Interpretada por Virginia Madsen) y sus hijos, suele suspirar aliviado. Le consuela estar lejos de las omnipresentes cámaras, de los controles de identidad, de las constantes tareas de mantenimiento y actualización de los complejos firewalls electrónicos y otras medidas de defensa, que se han convertido en práctica normal en esta era en la que todo se hace a través de la red: la comunicación, el comercio y el crimen. Pero lo que Jack no puede sospechar es que, al volver a casa, cada uno de sus movimientos es observado furtivamente y que pronto su vida y la de su familia se convertirán en una pesadilla.",
