   "actors": "Sam Worthington,Zoe Saldana,Sigourney Weaver",
   "synopsis": "En Avatar: El camino del agua, nos trasladamos diez años después de la primera batalla de Pandora entre los Na’vi y los humanos, Jake Sully (Interpretado por Sam Worthington) vive tranquilamente con su familia y su tribu. Él y Ney’tiri han formado una familia y hacen todo lo posible por permanecer juntos, debido a los problemas matrimoniales y a los roles que cada uno debe que desempeñar dentro de la tribu. Sin embargo, deben abandonar su hogar y explorar diferentes e inhospitas regiones de Pandora, adentrándose en el mar y haciendo pactos con otros Na’vi de dichas regiones.\nCuando una antigua amenaza resurge, Jake debe volver a librar una difícil guerra contra los humanos. Pese a la adversidad, Jake acaba haciendo nuevos aliados, algunos de los cuales ya viven entre los Na’vi y otros con nuevos avatares. Con una nueva guerra en marcha, Jake y Ney’tiri tendrán que hacer todo lo posible para permanecer juntos y cuidar de su familia y su tribu.",
