   "actors": "Gustaf Skarsgård,Matias Varela,Josefin Neldén",
   "synopsis": "On the eve of June 28th, 2011 Swedish journalists Martin Schibbye and Johan Persson put everything at stake by illegally crossing the border from Somalia into Ethiopia. After months of research, planning and failed attempts, they were finally on their way to report on how the ruthless hunt for oil affected the population of the isolated and conflict-ridden Ogaden region. Five days later they lay wounded in the desert sand, shot and captured by the Ethiopian army. But when their initial reportage died, another story began. A story about lawlessness, propaganda and global politics. After a Kafkaesque trial they were sentenced to eleven years in prison for terrorism. And they were far from alone. Their cellmates were journalists, writers and politicians persecuted for not bowing down to dictatorship. Their reportage about oil was transformed into a story about ink, and their daily lives turned into a fight for survival inside the notorious Kality prison in Addis Ababa. Exposed to deadly diseases, daily beatings and fierce repression - deprived of their shoelaces and their freedom of speech - they fought to preserve the most valuable thing of all: the freedom to determine who you are and what you believe. This is their story of 438 days of hell.",
   "poster": "https://dio3ka.lpsyujwj.xyz/public/images/af59cb1e-fb0b-48ed-9526-84e7aa92c64c",
