   "synopsis": "Leona, Ariela es una joven judeo-mexicana con un espiritu rebelde para los estándares de su comunidad. Sus amigas se preparan para casarse con mucha emoción y todas celebran por ello. Incluso le presentan a cualquier cantidad de prospectos para que pronto haga lo mismo a sus 25 años.\nSin embargo, ella trata de escapar de estos ritos y prefiere ir a pintar murales en las calles de la ciudad, con lo que hace algo de dinero. Un día, mientra está trabajando, conoce a Iván, un chico hijo de artistas, por quien se siente atraída inmediatamente. Mientras él le presenta un nuevo mundo, el amor va floreciendo. El problema es que al no ser judio, Ariela empieza a recibir las amenazas de expulsión de la comunidad por parte de su familia, amigos e incluso de gente que ni siquiera conoce pero que ya saben de su caso.",
