   "synopsis": "El año de la furia, Montevideo, 1972. Mientras el país se despeña irremisiblemente hacia el precipicio de la dictadura, Diego y Leonardo, dos guionistas de un conocido programa de televisión, luchan por mantener su integridad ante las presiones de sus superiores para que rebajen el tono de sus mordaces sátiras políticas y eviten ofender a los altos militares que se están apoderando del control del país.\nParalelamente, del lado de los opresores, Rojas, un teniente del ejército que ha sido presionado para torturar a militantes o simpatizantes de la guerrilla de los Tupamaros, exorciza sus demonios con Susana, una prostituta con la que encuentra una suerte de refugio emocional ante su sentimiento de culpa. Poco a poco, las confluyentes vidas de los guionistas y del militar se ven profundamente afectadas por el yugo de la dictadura que se va cerniendo sobre ellos, y tanto uno como otros luchan por encontrar una escapatoria, una salida digna que les permita aguantarse la mirada ante el espejo.",
