   "synopsis": "Es la oficina de una pequeña sucursal de la empresa papelera \"Dunder mingtian6.com Mifflin\", donde el día a día de un grupo de oficinistas está lleno de disparatada diversión bajo el liderazgo del muy desubicado director regional Michael (Steve Carell). Jim (John Krasinski) es un bromista ingenioso y rápido que se pasa el día ideando diferentes ideas para atormentar a su colega intelectual Dewitt (Rainn Wilson) que se sienta frente a él, quien se molesta en todo momento y acosa secretamente a Jim en el trabajo y lo ve como su mayor competencia para el ascenso; el compañero de bromas de Jim es La compañera de travesuras de Jim es la recepcionista Pam (Jenna Fischer), y se ríen sin parar, pero Pam tiene un prometido, así que Jim no puede estar muy impresionado con ella. En la oficina también viven Angela (Angela Kinsey), una excéntrica mujer mayor, Oscar (Oscar Nuñez), un contable gay que es discriminado por Michael, y Ryan (B.J. Novak), un becario que intenta desesperadamente encajar, pero independientemente de que todos se lleven bien o no, el consenso es que Michael, el gerente, es el mayor grano en el culo de la sala. ...",
