   "synopsis": "The Office sigue el día a día en la vida de unos excéntricos trabajadores de la empresa Dunder Mifflin, de forma fresca y divertida, y con apariencia de pseudo-documental. Adaptación por parte de Grez Daniela de la serie británica del mismo nombre, ‘The Office’ parodia la cultura americana a través de las vivencias de sus protagonistas.\nEl serio pero despistadísimo director Michael Scott se considera un magnífico jefe y mentor, pero realmente inspira más críticas y risas a sus empleados que respeto. Ryan Howard es un becario recién llegado y a través de cuyos ojos conoceremos a los distintos trabajadores de Dunder Mifflin.\nEntre estos empleados se encuentra Pam Beesley, una vendedora que, aunque lleva trabajando años en Dunder Mifflin, lo considera algo temporal mientras logra ganarse la vida como artista. También está Jim Halpert, uno de los mejores vendedores a pesar de sus reparos de hacer carrera en la oficina. La relación de Jim y Pam es muy cercana, y eso provoca que haya rumores entre sus compañeros de trabajo, sobre todo porque Pam está comprometida desde hace tres años con Roy Anderson, un trabajador del almacén. Un compromiso que, por otro lado, la trae por la calle de la amargura al ser eterno y, en apariencia, destinado a todo menos a una boda.",
   "poster": "https://dio3ka.lpsyujwj.xyz/public/images/b12ec1ed-ae4c-4a81-9dd1-88d5099cc273.jpg",
   "landscape": "https://dio3ka.lpsyujwj.xyz/public/images/f59101d0-fcbf-4e20-97b6-08ec78c5fafc.jpg",
   "backdrop": "https://dio3ka.lpsyujwj.xyz/public/images/f59101d0-fcbf-4e20-97b6-08ec78c5fafc.jpg",
   "type": "teleplay",
   "alias": "The Office S6",
