   "synopsis": "En una Corte Imperial en la antigua China, han pasado algunos meses desde que una chica de 17 años conocida como Maomao fue secuestrada y obligada a trabajar como una sirviente de bajo rango para el palacio del emperador. Aún así, se las arregla para mantener su espíritu curioso y pragmático, planeando trabajar hasta que sus años de servidumbre terminen. Un día, sin embargo, se da cuenta de que dos hijos del emperador han caído gravemente enfermos, por lo que decide actuar en secreto, utilizando su experiencia como farmacéutica criada en un barrio pobre. A pesar de los esfuerzos de Maomao por permanecer anónima, pronto llama la atención de Jinshi, un eunuco influyente que reconoce su talento. Maomao entonces pronto comienza a ganar posiciones en el imperio, y gradualmente comienza a hacerse de un nombre utilizando su conocimiento y su excéntrica personalidad para resolver misterios médicos.",
