   "actors": "",
   "synopsis": "Los insultos dirigidos a Saku Chitose son pan de cada día. Apodado \"el mujeriego sinvergüenza de la Clase 5\", es constantemente difamado en línea por aquellos que sienten celos de su popularidad. Afortunadamente, esto apenas afecta la confianza de Saku. Fuera de los foros de internet de nicho, es la figura respetable que sus compañeros admiran y un estudiante modelo en quien sus profesores confían. Con el inicio de su segundo año de secundaria, Saku se reúne con sus viejos amigos y hace nuevos, todos pertenecientes a la élite social de la escuela. Sin embargo, la diversión se ve interrumpida cuando el profesor tutor de Saku le pide que convenza a su compañero de clase recluso, Kenta Yamazaki, para que regrese a la escuela. Deseando resolver las cosas rápidamente, Saku visita la casa de Kenta al día siguiente. Pero la tarea resulta ser más desafiante de lo que esperaba cuando descubre que Kenta está completamente en contra de Saku. Si quiere preservar su impecable imagen, Saku debe encontrar la manera de ganarse a Kenta y llevarlo de vuelta a la escuela.",
