   "synopsis": "En este nuevo y extraño mundo, Noriko es considerada por error o destino como \"El Despertar\", una figura profética ligada a un poder colosal capaz de despertar a un dragón o demonio celestial. Justo después de llegar, un monstruo gigante la ataca, pero es salvada por Izark Kia Tarj, un espadachín solitario y temido que no habla su idioma. Al no tener fuerzas ni conocer el entorno, Noriko decide acompañar a Izark. Mientras viajan juntos, ella aprende el idioma local y ambos se ven envueltos en un conflicto político y de naciones que quieren capturarla por su supuesto poder, desarrollando un profundo vínculo romántico y de protección mutua.",
