   "synopsis": "Tras una dura campaña para vencer al Rey Demonio, el príncipe Henri rompe su compromiso públicamente y la tacha de \"inútil\" o \"lastre\" por no haber participado en la lucha directa de primera línea. Mientras el príncipe y su grupo son aclamados como héroes, Romelia regresa en desgracia a su empobrecida tierra natal. No obstante, durante el viaje, Romelia se encargó de administrar, recopilar información, negociar y dirigir la retaguardia para asegurar la victoria. Al percatarse de que la amenaza de los restos del ejército demoníaco y la crisis del reino siguen latentes, decide no rendirse. Utilizando su aguda inteligencia, capacidad estratégica y dotes de liderazgo, comienza a organizar un nuevo ejército desde sus dominios para proteger a su gente y enfrentar las amenazas políticas y militares.",
