   "synopsis": "Satoko, la hija mayor de la honorable familia Kirigaya, ha recibido numerosas propuestas de matrimonio de hombres cautivados por su belleza y gracia. Sin embargo, las ha rechazado todas debido a una cardiopatía secreta. A pesar de su condición, Satoko aún desea encontrar un esposo para tranquilizar a su querido padre. Durante un paseo, Satoko es secuestrada por un grupo de mercenarios, entre ellos Shinpei Gotou, un legendario asesino encargado de ejecutarla. Satoko intenta sobornar a Gotou para que la libere, pero fracasa. Sin más opciones, Satoko se arriesga: fingiendo amor a primera vista, le pide matrimonio. Inesperadamente, Gotou acepta y jura protegerla. Mientras la pareja escapa hacia la libertad, Satoko lucha por mantener la farsa y comprender al misterioso hombre con el que se ha fugado.",
