   "synopsis": "Es un personaje de dibujos animados creado por los estudios de animación Hanna-Barbera. Se trata de un caballo antropomórfico y parlante cuyas aventuras se emitieron por los canales de televisión sindicados estadounidenses el 29 de septiembre de 1959, dentro del programa infantil, que llevaba su propio nombre, el show de Tiro Loco McGraw. Era éste el tercer programa infantil producido por Hanna-Barbera para la televisión tras Ruff y Reddy y El Show de Huckleberry Hound. El show de Tiro Loco McGraw incluía además las series de Canuto y Canito y de Super Fisgón y Despistado, y tenía una duración de media hora.",
