   "actors": "",
   "synopsis": "El popular deporte electrónico DARK MACHINE cautiva a personas de todo el mundo y ha transformado la economía de Japón, donde existe una zona económica exclusiva llamada \"Golden Valley\" (Valle Dorado). Ajima es el séptimo \"Senki\" —un título otorgado al jugador más fuerte del juego— y controla de hecho la región a través de DARK MACHINE. El protagonista, Kairi, llega a Golden Valley con las últimas palabras de su difunto abuelo en mente: \"Encuentra a Senki\". Entonces se topa con una joven llamada Rudora, a quien persigue un subordinado de Ajima. Kairi se convierte en jugador de DARK MACHINE tras conectarse con Rudora, y su talento florece con cada feroz batalla. ¿Podrá Kairi enfrentarse a Senki y forjar su propio destino? Su batalla para alcanzar la cima de DARK MACHINE comienza ahora.",
