   "actors": "",
   "synopsis": "20 years ago, the combining robot Dandivine defeated the mysterious invaders known as Aposdoll. The toy manufacturing company Kasuga celebrated humanity's victory by turning Dandivine into a popular toy-line, but poor management and over-reliance on the Dandivine line has pushed the company to the brink of bankruptcy, causing Kasuga company president Genjuro Shijima to wish for Dandivine's revival, even if it means disturbing the world's peaceful state. Suddenly, as if in response to Genjuro's wish, the Aposdoll reappear in Tokyo, sending the peace-loving people into a panic. In order to save the world, ordinary high school student Gekiha Shijima boards the Dandivine at the urging of his uncle, Dandivine's former pilot, Yusaku Kuroiwa. Why have the Aposdoll resurfaced? And will Kasuga reign supreme over the toy industry once again? A new battle is about to begin.",
