   "director": "Lee Unkrich,Adrian Molina",
   "actors": "Anthony Gonzalez,Gael García Bernal,Benjamin Bratt",
   "synopsis": "Pixar lo ha vuelto a lograr, ‘Coco’ sitúa otra vez al cine de animación en un nivel superior, la productora de los sueños nos trae una mágica explosión de creatividad, ingentes dosis de entretenimiento, valores a borbotones, una hipnótica banda sonora y un mundo rebosante de color.\nSin duda alguna estamos ante la película de animación del año, la mejor de la productora desde ‘Inside Out’, uno de los títulos imprescindibles para grandes y chicos y una clara candidata a llevarse el Oscar en su categoría. ‘Coco’ no tiene la personalidad de ‘Del revés’ pero su guion rebosa solidez, tampoco ofrece grandes dosis de humor, pero Lee Unkrich y Adrián Molina han logrado crear un mundo con la idónea proporción de elementos capaz de ofrecer un sensacional producto. Todo ello acompañado de unos adorables personajes, del primero al último, que te seducirán con su entrañable y dulce hacer mejicano del que tan inteligentemente se ha empapado la película.",
   "poster": "https://dio3ka.lpsyujwj.xyz/public/images/85085c29-6582-4b70-9706-96e99138da7c.jpg",
