   "synopsis": "Chihiro es una niña de diez años que viaja en automóvil con sus padres. Después de atravesar un túnel, llegan a un mundo fantástico, en el que no hay lugar para los seres humanos, sólo para los dioses. Cuando descubre que sus padres han sido convertidos en cerdos, Chihiro perderá toda esperanza, sin embargo, con la ayuda de seres como Haku o el anciano esclavo de las calderas, podrá encontrar su valentía y enfrentar los obstáculos necesarios, para salvar a su familia. Hayao Miyazaki tomo la decisión de que la película estaría basada en la hija de diez años de un amigo que iba a visitar su casa cada verano, y desde su estreno el largometraje es en uno de los más taquilleros en Japón, contando con una recaudación aproximada de 229 millones de dolares.",
